var RX_BODY = window.RX_BODY || {};

/* ── ١) بدائل النيكوتين ───────────────────────────────────── */
RX_BODY['nicotine-replacement-therapy'] = {
  what: {
    ar: 'بدائل النيكوتين مجموعة منتجات تعطي الجسم نيكوتيناً نقيّاً بلا احتراق ولا دخان ولا قطران، فتُسمّى في النشرات معينات الإقلاع عن التدخين. وهي صنفان: بطيء طويل الأثر وهو اللصقة الجلدية التي تُعطي مدداً ثابتاً طوال اليوم، وسريع قصير الأثر يُطفئ نوبة الشوق المفاجئة ويشمل العلكة وأقراص المصّ والأقراص الذائبة تحت اللسان وجهاز الاستنشاق وبخّاخ الفم وبخّاخ الأنف. وأكثرها يُصرف بلا وصفة، وتقول هيئة الصحة البريطانية إنها آمنة ومثبتة الأثر.',
    en: 'Nicotine replacement therapy is a group of products that give the body pure nicotine with no burning, smoke or tar, and the leaflets call them smoking cessation aids. They come in two kinds: a slow long-acting form, the skin patch, which supplies a steady level through the day, and fast short-acting forms that put out a sudden craving, including gum, lozenges, microtabs, an inhalator, a mouth spray and a nasal spray. Most are sold without prescription, and the British health service calls them safe and proven to work.'
  },
  why: {
    ar: 'تُستعمل لهدف واحد: مساعدة المدخّن على التوقّف. فحين تنقطع السيجارة تظهر أعراض السحب من توتّر وعصبيّة وأرق وضعف تركيز وجوع وشوق ملحّ، وهذه الأعراض هي التي تُعيد أكثر الناس إلى العلبة في الأيام الأولى. تعطي البدائل نيكوتيناً يكفي لكبح هذه الأعراض حتى تمرّ. وتقول النشرة البريطانية إنها تضاعف فرصة الإقلاع النهائي، وإن الجمع بين لصقة تُعطي الأساس ومنتج سريع يُستعمل عند الشوق هو أنجع الطرق، وإن نتيجتها تكون أفضل حين تُرافقها متابعة أو استشارة سلوكية.',
    en: 'They are used for one purpose: to help a smoker stop. When cigarettes are cut off, withdrawal appears as tension, irritability, poor sleep, poor concentration, hunger and an insistent craving, and it is these symptoms that send most people back to the packet in the first days. The replacement supplies enough nicotine to hold those symptoms down until they pass. The British leaflet states that it doubles the chance of quitting for good, that combining a patch for the baseline with a fast product for cravings is the most effective approach, and that results are better when behavioural support or counselling goes with it.'
  },
  how: {
    ar: 'نيكوتين السيجارة يبلغ الدماغ في ثوانٍ فيُطلق دفعة من الدوبامين، وهذه الدفعة السريعة هي التي تصنع الإدمان وتربطه بالسيجارة نفسها. أما البدائل فتُدخل النيكوتين ببطء وبمقدار أقلّ عبر الجلد أو بطانة الفم أو الأنف، فتكفي لإسكات أعراض السحب دون أن تُحدث تلك الذروة التي تُثبّت العادة. والأهمّ أن الأذى الأكبر في التدخين ليس من النيكوتين وحده بل من القطران وأول أكسيد الكربون وآلاف مركّبات الاحتراق، وهذه كلها غائبة عن البديل.',
    en: 'Nicotine from a cigarette reaches the brain in seconds and releases a surge of dopamine, and it is that rapid surge which creates the addiction and ties it to the cigarette itself. The replacements instead let nicotine in slowly and in smaller amounts through the skin or the lining of the mouth or nose, enough to silence withdrawal without producing the peak that fixes the habit. More importantly, the greater harm of smoking comes not from nicotine alone but from tar, carbon monoxide and thousands of combustion products, and none of these is present in the replacement.'
  },
  effects: {
    ar: 'المشترك بين كل الأشكال صداع وغثيان ودوخة. واللصقة تُحدث احمراراً أو حكّة أو تورّماً في موضع لصقها، وتُسبّب اضطراب نوم وأحلاماً حيّة عند بعض الناس ويحلّ ذلك بنزعها قبل النوم. والعلكة تُسبّب فواقاً وحرقة معدة وغثياناً ومشاكل في الفم والأسنان وألماً في الفكّ من كثرة المضغ. وجهاز الاستنشاق يهيّج الفم والحلق ويُحدث سعالاً. وبخّاخ الأنف يهيّج الأنف والعين والحلق، وهذا التهيّج يخفّ عادةً خلال أيام قليلة من البدء.',
    en: 'Common to all forms are headache, nausea and dizziness. The patch causes redness, itching or swelling where it is applied, and in some people disturbed sleep and vivid dreams, which is solved by removing it before bed. The gum causes hiccups, heartburn, nausea, mouth and tooth problems and jaw ache from all the chewing. The inhalator irritates the mouth and throat and provokes a cough. The nasal spray irritates the nose, eyes and throat, and this irritation usually eases within a few days of starting.'
  },
  warning: {
    ar: 'توقّف واطلب المساعدة العاجلة إذا جاءك خفقان سريع أو قويّ أو غير منتظم، أو ضيق نفس، أو طفح شديد أو تورّم، أو تنفّط داخل الفم، أو قيء وإسهال وضعف، أو نوبة تشنّج: هذه علامات زيادة النيكوتين أو تحسّس منه. ولا تدخّن ولا تستعمل أي منتج نيكوتين آخر معها إطلاقاً، فالجمع يُنتج جرعة زائدة كما تنصّ النشرة. واذهب للطوارئ فوراً إذا بلع طفل أو حيوان علكة ممضوغة أو لصقة مستعملة، فالمتبقّي فيها يكفي لتسميمه. وإذا صار ألم صدر أو تفاقم مرض قلبي عندك فراجع طبيبك.',
    en: 'Stop and seek urgent help for a fast, pounding or irregular heartbeat, difficulty breathing, a severe rash or swelling, blisters inside the mouth, vomiting with diarrhoea and weakness, or a seizure: these are signs of too much nicotine or of an allergy to it. Never smoke or use any other nicotine product alongside it, because combining them produces an overdose, as the leaflet states. Go to emergency at once if a child or a pet swallows chewed gum or a used patch, since what remains in them is enough to poison them. And if chest pain appears or a heart condition worsens, contact your doctor.'
  },
  interact: {
    ar: 'التعارض الأخطر هو مع السيجارة نفسها: لا يُجمع بينهما لأن النيكوتين يتراكم إلى حدّ ضارّ. وتذكر النشرة الأمريكية احتمال تفاعل مع الباراسيتامول وأن جرعات أدوية أخرى قد تحتاج تعديلاً. والأمر الذي يغيب عن كثيرين أن الإقلاع نفسه لا البديل هو ما يغيّر الأدوية: دخان التبغ يُحرّض إنزيماً كبديّاً اسمه سيتوكروم واحد أ اثنان، فإذا توقّف التدخين هبط نشاطه وارتفعت مستويات أدوية مثل الثيوفيلين والكلوزابين والأولانزابين والكافيين والوارفارين. والبديل النيكوتيني لا يمنع هذا لأن السبب ليس النيكوتين.',
    en: 'The most dangerous interaction is with the cigarette itself: the two are not combined, because nicotine builds up to a harmful level. The American leaflet notes a possible interaction with paracetamol and that the doses of other medicines may need adjusting. What escapes many people is that quitting itself, not the replacement, is what changes medicines: tobacco smoke induces a liver enzyme called cytochrome 1A2, so when smoking stops its activity falls and the levels of drugs such as theophylline, clozapine, olanzapine, caffeine and warfarin rise. The nicotine replacement does not prevent this, because nicotine is not the cause.'
  },
  avoid: {
    ar: 'يُستشار الطبيب أو الصيدلي قبل البدء عند مرض القلب أو الدورة الدموية، وخاصةً من أصابته جلطة قلبية حديثة أو عنده ذبحة أو اضطراب نظم أو ضغط غير منضبط، وإن كانت اللصقة تُعدّ مقبولة عادةً لمريض قلب مستقرّ. ويُستشار كذلك عند قرحة المعدة وفرط نشاط الغدة الدرقية والسكّري وورم الكظر. والنشرة الأمريكية تضع الحمل والرضاعة خارج الاستعمال الذاتي، وتنبّه الموسوعة الطبية إلى احتمال أثر على رئة الجنين وقلبه ودماغه. ودون سنّ الثامنة عشرة يُستشار مختصّ. وأشكال الفم لا تُلائم من عنده مشكلة في الفكّ أو الأسنان.',
    en: 'Ask a doctor or pharmacist before starting if you have heart or circulatory disease, especially after a recent heart attack, or with angina, an irregular rhythm or uncontrolled blood pressure, although the patch is generally considered acceptable for a stable cardiac patient. Advice is also needed with stomach ulcer, an overactive thyroid, diabetes and adrenal tumour. The American leaflet places pregnancy and breastfeeding outside self-treatment, and the medical encyclopaedia warns of possible effects on the unborn child’s lungs, heart and brain. Under eighteen, a specialist should be consulted. Oral forms do not suit anyone with jaw or dental problems.'
  },
  updated: '2026-09-10',
  src: [
    'https://medlineplus.gov/druginfo/meds/a601084.html',
    'https://medlineplus.gov/druginfo/meds/a684056.html',
    'https://medlineplus.gov/ency/article/007438.htm',
    'https://www.nhs.uk/better-health/quit-smoking/ready-to-quit-smoking/quit-with-nicotine-replacement-therapies-nrt/',
    'https://pubmed.ncbi.nlm.nih.gov/17823102/'
  ]
};

/* ── ٢) التيمولول ─────────────────────────────────────────── */
RX_BODY['timolol'] = {
  what: {
    ar: 'التيمولول قطرة عين من فصيلة حاصرات بيتا، وهي الفصيلة نفسها التي تُعطى أقراصاً لضغط الدم والقلب. ويأتي محلولاً سائلاً ومحلولاً هلاميّ القوام ممتدّ الأثر يبقى على سطح العين أطول. وهو من أقدم أدوية الزرق وأكثرها استعمالاً، ويدخل في تركيبات مشتركة مع الدورزولاميد أو اللاتانوبروست في قنّينة واحدة. والمهمّ الذي يُغفل عنه أن هذه القطرة لا تبقى في العين: جزء منها ينزل من قناة الدمع إلى الحلق فيُمتصّ إلى الدم ويعمل في القلب والرئتين.',
    en: 'Timolol is an eye drop from the beta-blocker family, the same family given as tablets for blood pressure and the heart. It comes as a liquid solution and as a gel-forming, longer-acting solution that stays on the eye surface longer. It is one of the oldest and most widely used glaucoma medicines, and it appears in combination bottles with dorzolamide or latanoprost. The point most often missed is that this drop does not stay in the eye: part of it drains through the tear duct into the throat, is absorbed into the blood and acts on the heart and lungs.'
  },
  why: {
    ar: 'يُوصف لعلاج الزرق، وهو حالة يرتفع فيها ضغط داخل العين حتى يُتلف العصب البصري تدريجياً ويقضم مجال الرؤية من أطرافه دون أن يشعر صاحبه إلا بعد فوات جزء منه. ويُستعمل كذلك لارتفاع ضغط العين قبل أن يظهر ضرر العصب. والغاية من الدواء ليست إزالة أعراض يشكو منها المريض، فالزرق أكثره صامت، بل حفظ ما بقي من البصر ومنع تقدّم الضرر. ولذلك يُستعمل مدى الحياة غالباً، وتركه لأن العين لا تؤلم هو أشيع سبب لخسارة البصر في هذا المرض.',
    en: 'It is prescribed for glaucoma, a condition in which the pressure inside the eye rises until it gradually damages the optic nerve and eats away the field of vision from its edges, without the person noticing until part of it is already gone. It is also used for raised eye pressure before nerve damage appears. The aim is not to relieve symptoms the patient complains of, since most glaucoma is silent, but to preserve what sight remains and stop the damage advancing. It is therefore usually lifelong, and stopping it because the eye does not hurt is the commonest cause of sight loss in this disease.'
  },
  how: {
    ar: 'داخل العين جسمٌ يُسمّى الجسم الهدبي يُفرز سائلاً مائياً باستمرار، ويخرج هذا السائل من زاوية بين القزحية والقرنية. فإذا زاد الإنتاج أو ضاق المخرج ارتفع الضغط. ويعمل التيمولول على الجانب الأول: يحجب مستقبلات بيتا على الجسم الهدبي فيقلّ إفراز السائل من أصله، فينزل الضغط. وهذه المستقبلات نفسها موجودة في القلب فتُبطئه، وفي الشعب الهوائية فتُضيّقها، ومن هنا جاءت كل تحذيراته المهمّة: ما ينفع العين قد يؤذي قلباً ضعيفاً أو رئةً ربويّة.',
    en: 'Inside the eye a structure called the ciliary body continuously secretes a watery fluid, which leaves through an angle between the iris and the cornea. If production rises or the outlet narrows, pressure goes up. Timolol works on the first side: it blocks beta receptors on the ciliary body so less fluid is made in the first place, and the pressure falls. The same receptors exist in the heart, where they slow it, and in the airways, where blocking them narrows them, and from this come all its important warnings: what helps the eye can harm a weak heart or an asthmatic lung.'
  },
  effects: {
    ar: 'أكثر ما يُلاحظ تهيّج في العين مع لسع أو حرقة عند التقطير، وقد يأتي ازدواج في الرؤية أو تشوّش مؤقّت. وتُذكر في النشرة أيضاً أعراض عامّة سببها ما يُمتصّ إلى الدم: صداع ودوخة وغثيان، وحالة اكتئاب. وتقلّ هذه الأعراض العامّة كثيراً بحيلة بسيطة: أغمض عينك بعد التقطير واضغط بإصبعك على الزاوية الداخلية عند الأنف، فيقلّ ما ينزل من الدواء إلى الحلق. وإن كانت الرؤية غير واضحة بعد القطرة فلا تقُد حتى تصفو.',
    en: 'What is noticed most is eye irritation with stinging or burning on instillation, and there may be double vision or temporary blurring. The leaflet also lists general symptoms caused by what is absorbed into the blood: headache, dizziness, nausea and depression. These general effects are much reduced by a simple trick: close the eye after instilling and press a finger on the inner corner beside the nose, so less of the drug drains into the throat. And if vision is unclear after the drop, do not drive until it settles.'
  },
  warning: {
    ar: 'اطلب الطوارئ فوراً عند ضيق نفس أو صفير أو نوبة ربو بعد القطرة، فالنشرة الرسمية تسجّل وفيات بتشنّج القصبات لدى مرضى الربو بعد التقطير في العين لا الفم. واطلبها كذلك عند نبض بطيء جداً أو غير منتظم، أو إغماء، أو زيادة وزن مفاجئة، أو تورّم القدمين والساقين، فهذه علامات قصور قلب. وتوقّف وراجع طبيبك عند ألم شديد في العين أو نقص مفاجئ في الرؤية أو احمرار وإفراز. وأخبر أي جرّاح أو طبيب تخدير أنك تستعمل هذه القطرة قبل أي عملية. واتصل بطبيبك فوراً إن حملتِ أثناء العلاج.',
    en: 'Get emergency help at once for breathlessness, wheeze or an asthma attack after the drop; the official label records deaths from bronchospasm in asthmatic patients following instillation into the eye, not the mouth. Seek it too for a very slow or irregular pulse, fainting, sudden weight gain, or swelling of the feet and lower legs, which are signs of heart failure. Stop and contact your doctor for severe eye pain, a sudden drop in vision, or redness with discharge. Tell any surgeon or anaesthetist that you use this drop before an operation. And call your doctor at once if you become pregnant during treatment.'
  },
  interact: {
    ar: 'إن كنت تستعمل قطرة عين أخرى فباعد بينها وبين التيمولول مدّة كافية كما تنصّ النشرة، وإلا غسلت الثانية الأولى قبل أن تعمل. والتعارض الأهمّ مع الأدوية التي تُبطئ القلب أو تخفض الضغط بالفم، وعلى رأسها حاصرات بيتا الفموية وحاصرات الكالسيوم مثل الفيراباميل، فيجتمع أثرهما على القلب. وأخبر طبيبك بكل ما تأخذه فقد يحتاج تعديل جرعات. ومريض السكّري ينتبه بوجه خاص: حاصرات بيتا قد تُخفي علامات هبوط السكّر كالخفقان والرجفة فيقع الهبوط دون إنذار.',
    en: 'If you use another eye drop, leave an adequate gap between it and timolol as the leaflet directs, otherwise the second washes out the first before it can work. The most important interaction is with medicines taken by mouth that slow the heart or lower blood pressure, above all oral beta-blockers and calcium blockers such as verapamil, whose effect on the heart adds to it. Tell your doctor everything you take, as doses may need changing. People with diabetes should take particular care: beta-blockers can mask the warning signs of low blood sugar, such as palpitations and trembling, so a hypo arrives unannounced.'
  },
  avoid: {
    ar: 'ممنوع على مريض الربو أو من له تاريخ ربو، وعلى مريض الانسداد الرئوي المزمن الشديد، لأن حصر بيتا يزيد مقاومة المجرى الهوائي. وممنوع كذلك في بطء الجيب وحصار العقدة الأذينية البطينية من الدرجة الثانية أو الثالثة وقصور القلب الظاهر والصدمة القلبية. ولا يأخذه من تحسّس من حاصرات بيتا. ويُنبَّه عليه في الوهن العضلي الوبيل لأنه قد يزيد ضعف العضلة، وفي مرض الدرقية والسكّري. والحمل والرضاعة يُتجنّب فيهما ما لم يقرّر الطبيب. ومن يلبس عدسات لاصقة لينة ينزعها قبل التقطير ولا يعيدها إلا بعد أن يمرّ وقت كافٍ.',
    en: 'It is forbidden in asthma or a history of asthma and in severe chronic obstructive pulmonary disease, because beta blockade increases airway resistance. It is also forbidden in sinus bradycardia, second or third degree atrioventricular block, overt heart failure and cardiogenic shock. Anyone who has reacted to beta-blockers must not take it. Caution is flagged in myasthenia gravis, where it can worsen muscle weakness, and in thyroid disease and diabetes. Pregnancy and breastfeeding are to be avoided unless the doctor decides otherwise. Anyone wearing soft contact lenses removes them before instilling and does not put them back until enough time has passed.'
  },
  updated: '2026-09-10',
  src: [
    'https://medlineplus.gov/druginfo/meds/a682043.html',
    'https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=45ac65b3-19f7-4f33-aebf-cadd3daa4bf1'
  ]
};

/* ── ٣) اللاتانوبروست ─────────────────────────────────────── */
RX_BODY['latanoprost'] = {
  what: {
    ar: 'اللاتانوبروست قطرة عين من فصيلة نظائر البروستاغلاندين، وهي فصيلة صارت العلاج الأول للزرق في أكثر العالم لأنها تُخفض الضغط بقطرة واحدة في اليوم وتُمتصّ إلى الدم بمقدار لا يُذكر، فلا تحمل مخاطر القلب والرئة التي تحملها قطرات حاصرات بيتا. ويأتي محلولاً في قنّينة تحتاج حفظاً بارداً قبل الفتح في بعض التركيبات، وله أشكال بلا مادّة حافظة لمن تتهيّج عينه من البنزالكونيوم. ويدخل مع التيمولول في قنّينة مشتركة.',
    en: 'Latanoprost is an eye drop from the prostaglandin analogue family, a class that has become the first-line treatment for glaucoma in most of the world because it lowers pressure with a single drop a day and is absorbed into the blood in negligible amounts, so it does not carry the heart and lung risks that beta-blocker drops do. It comes as a solution in a bottle that in some formulations needs cold storage before opening, and preservative-free versions exist for eyes irritated by benzalkonium. It is also combined with timolol in one bottle.'
  },
  why: {
    ar: 'يُوصف للزرق ولارتفاع ضغط العين. والزرق مرض يرفع الضغط داخل العين حتى يُتلف العصب البصري ببطء، ويأكل مجال الرؤية من الأطراف نحو المركز، ولا يشعر به صاحبه غالباً حتى يكون قد فقد جزءاً لا يعود. وليس للدواء أثر يُحسّ به المريض: لا يُحسّن الرؤية ولا يزيل شكوى، بل يمنع الخسارة القادمة. ولذلك تُقاس فائدته بجهاز الطبيب لا بشعور المريض، ويُستعمل سنوات طويلة، وأشيع خطأ فيه هو تركه لأن العين لا تشتكي.',
    en: 'It is prescribed for glaucoma and for ocular hypertension. Glaucoma raises the pressure inside the eye until it slowly damages the optic nerve, eating the field of vision from the edges inward, and the person usually feels nothing until a part is lost that will not come back. The medicine produces no effect the patient can feel: it does not improve vision or remove a complaint, it prevents the loss to come. Its benefit is therefore measured by the doctor’s instrument rather than by how the patient feels, it is used for many years, and the commonest mistake is stopping it because the eye is not complaining.'
  },
  how: {
    ar: 'يُفرز داخل العين سائل مائي باستمرار ويخرج بطريقين: الطريق التقليدي عبر الشبكة التربيقية في زاوية العين، والطريق العنبي الصلبوي عبر جدارها. ولا يمسّ اللاتانوبروست الإنتاج بل يوسّع المخرج: يرتبط بمستقبل البروستاغلاندين فيُرخي أنسجة الطريق العنبي الصلبوي ويزيد جريان السائل خارجاً، فينخفض الضغط. وهذا الارتباط نفسه يُنبّه الخلايا الصبغية في القزحية وفي جلد الجفن وجذور الرموش على إنتاج مزيد من الميلانين، ومن هنا جاءت آثاره التجميلية المميّزة.',
    en: 'Inside the eye a watery fluid is secreted continuously and leaves by two routes: the conventional route through the trabecular meshwork in the angle, and the uveoscleral route through its wall. Latanoprost does not touch production; it widens the exit. It binds to a prostaglandin receptor, relaxing the tissues of the uveoscleral route and increasing the outward flow of fluid, so pressure falls. That same binding prompts the pigment cells of the iris, the eyelid skin and the lash roots to make more melanin, and from this come its distinctive cosmetic effects.'
  },
  effects: {
    ar: 'أشيع ما يُشكى منه لسع أو حرقة أو حكّة أو تهيّج في العين، وجفافها، وإحساس بجسم غريب فيها، مع صداع أو دوخة. وأما الأثر الذي يفاجئ الناس فهو تغيّر اللون: تسودّ القزحية وتصير بنّية، وقد يكون هذا التغيّر دائماً؛ وتطول الرموش وتغلظ وتسودّ، وقد يبقى ذلك كذلك؛ ويسمرّ جلد الجفن حوله. وتزداد هذه الصبغة ما دام الدواء يُستعمل. والانتباه إليه أهمّ حين يُقطَّر في عين واحدة، لأن الفرق بين العينين يظهر ولا يُمحى.',
    en: 'The commonest complaints are stinging, burning, itching or irritation in the eye, dryness and a feeling of something in it, along with headache or dizziness. The effect that surprises people is the change of colour: the iris darkens towards brown, and this change may be permanent; the lashes grow longer, thicker and darker, and that too may persist; and the eyelid skin around them darkens. This pigmentation goes on increasing as long as the drug is used. It matters most when only one eye is treated, because the difference between the two shows and does not wash out.'
  },
  warning: {
    ar: 'راجع طبيب العيون بلا تأخير إذا صارت العين حسّاسة للضوء بشدّة، أو تغيّرت الرؤية أو ضبُبت، أو احمرّت العين أو الجفن، أو تورّم الجفن، أو صار في العين ألم متزايد أو إفراز. وتسجّل النشرة الرسمية حدوث وذمة بقعية بما فيها الوذمة البقعية الكيسية أثناء العلاج، وهي تُنقص الرؤية المركزية وتحتاج فحص قاع العين لا انتظاراً. ولا تُستعمل القطرة إن كانت العين ملتهبة التهاباً داخلياً نشطاً. وأخبر الطبيب إن كانت عدسة العين ممزّقة أو غائبة، وإن كان لك تاريخ التهاب داخل العين أو عدوى فيها.',
    en: 'See an eye doctor without delay if the eye becomes strongly sensitive to light, if vision changes or blurs, if the eye or eyelid reddens, if the lid swells, or if pain or discharge builds up. The official label records macular oedema, including cystoid macular oedema, occurring during treatment; it reduces central vision and needs an examination of the back of the eye rather than waiting. The drop is not used when there is active inflammation inside the eye. Tell the doctor if the lens of the eye is torn or missing, and if you have a history of inflammation inside the eye or of infection in it.'
  },
  interact: {
    ar: 'ليس لهذه القطرة تعارض دوائي جهازي يُذكر في نشرتها، لأن ما يصل منها إلى الدم ضئيل. والتنبيه العملي الوحيد المهمّ هو المباعدة بين القطرات: إن كنت تستعمل أكثر من قطرة للعين فاترك بينها فاصلاً كما تنصّ النشرة، وإلا جرفت القطرة التالية سابقتها قبل أن تُمتصّ. وقد ذُكر في الدراسات أن جمع نظيرين من البروستاغلاندين معاً قد يرفع الضغط بدل خفضه، فلا تُضاف قطرة من الفصيلة نفسها إلا بقرار الطبيب. وأخبر طبيبك بكل ما تستعمله للعين وللبدن.',
    en: 'This drop has no notable systemic drug interaction in its leaflet, because very little of it reaches the blood. The one important practical point is spacing: if you use more than one eye drop, leave a gap between them as the leaflet directs, otherwise the next drop washes the previous one away before it is absorbed. Studies have reported that combining two prostaglandin analogues together may raise pressure instead of lowering it, so a second drop of the same class is not added except by the doctor’s decision. Tell your doctor everything you use, for the eye and for the body.'
  },
  avoid: {
    ar: 'لا يأخذه من تحسّس من اللاتانوبروست أو من أحد مكوّنات القطرة. ويُنبَّه عليه في من له تاريخ التهاب داخل العين كالتهاب القزحية أو العنبية، ولا يُستعمل عموماً حين يكون هذا الالتهاب نشطاً. ويُحسب حسابه لمن عنده عوامل خطر للوذمة البقعية كغياب عدسة العين أو تمزّق محفظتها. وأخبري طبيبك إن كنتِ حاملاً أو تخطّطين للحمل أو ترضعين. ومن يلبس عدسات لاصقة ينزعها قبل التقطير ولا يعيدها إلا بعد مرور وقت كافٍ، لأن المادّة الحافظة تترسّب في العدسة اللينة.',
    en: 'It must not be used by anyone allergic to latanoprost or to any ingredient of the drop. Caution is flagged in anyone with a history of inflammation inside the eye such as iritis or uveitis, and it is generally not used while that inflammation is active. It is weighed carefully in people with risk factors for macular oedema, such as absence of the eye’s lens or a torn lens capsule. Tell your doctor if you are pregnant, planning pregnancy or breastfeeding. Contact lens wearers remove their lenses before instilling and do not replace them until enough time has passed, because the preservative deposits in a soft lens.'
  },
  updated: '2026-09-10',
  src: [
    'https://medlineplus.gov/druginfo/meds/a697003.html',
    'https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0f4881ec-2984-4853-bc25-5b14c3b79da7'
  ]
};

/* ── ٤) البيلوكاربين ──────────────────────────────────────── */
RX_BODY['pilocarpine'] = {
  what: {
    ar: 'البيلوكاربين دواء كوليني، أي أنه يُقلّد ناقلاً عصبياً اسمه الأسيتيل كولين. وله وجهان مختلفان تماماً: قطرة عين تُصنّف في فصيلة تُسمّى مضيّقات الحدقة، وقرص يُبلع لعلاج جفاف الفم. وقطرة العين من أقدم أدوية الزرق، وقد تراجع استعمالها المزمن لصالح القطرات الحديثة لأن آثارها البصرية مزعجة، لكنها بقيت سلاحاً مهمّاً في نوبة انسداد الزاوية الحادّة وقبل جراحة الليزر وبعدها، وفي فحص العين. وله شكل حديث لعلاج قِصر النظر الشيخوخي.',
    en: 'Pilocarpine is a cholinergic drug, meaning it imitates a nerve messenger called acetylcholine. It has two quite different faces: an eye drop classed among the miotics, or pupil constrictors, and a tablet swallowed for dry mouth. The eye drop is one of the oldest glaucoma medicines, and its long-term use has given way to newer drops because its visual effects are troublesome, yet it remains an important weapon in an acute angle-closure attack, before and after laser surgery, and in eye examination. A modern form treats age-related near-sight difficulty.'
  },
  why: {
    ar: 'تُستعمل القطرة في الزرق وارتفاع ضغط العين، ولمنع أو تقليل ارتفاع الضغط أثناء بعض جراحات الليزر وبعدها، ولتضييق الحدقة أثناء فحص العين، ولعلاج قصر النظر الشيخوخي عند البالغين بتصغير الحدقة حتى تُرى الأشياء القريبة أوضح. أما القرص المبلوع فله دواعٍ أخرى تماماً: جفاف الفم بعد العلاج الإشعاعي لسرطان الرأس والرقبة، وجفاف الفم في متلازمة شوغرن، وهي مرض مناعي يهاجم الغدد المفرزة للعاب والدمع فيجفّ الفم والعين.',
    en: 'The drop is used in glaucoma and ocular hypertension, to prevent or reduce a pressure rise during and after certain laser eye operations, to constrict the pupil during an eye examination, and to treat age-related difficulty with near vision in adults by shrinking the pupil so close objects are seen more clearly. The swallowed tablet has quite different indications: dry mouth after radiotherapy for head and neck cancer, and dry mouth in Sjogren syndrome, an immune disease that attacks the glands producing saliva and tears so the mouth and eyes dry out.'
  },
  how: {
    ar: 'الأسيتيل كولين هو الناقل الذي يأمر العضلات الملساء بالانقباض والغدد بالإفراز، والبيلوكاربين يجلس على مستقبله فيُنفّذ الأمر نفسه. في العين ينقبض عضل حدقة القزحية فتضيق الحدقة، وينشدّ عضل العين الهدبي فيُشدّ معه نسيج الزاوية وتُفتح مسالك التصريف، فيخرج السائل المحتبس وينخفض الضغط، وهذا هو المقصود في نوبة انسداد الزاوية. وفي الفم ينبّه الغدد اللعابية فتزيد إفرازها. والعضلات والغدد نفسها موجودة في القصبات والأمعاء والجلد، ومن هنا تأتي آثاره الجانبية العامّة.',
    en: 'Acetylcholine is the messenger that tells smooth muscle to contract and glands to secrete, and pilocarpine sits on its receptor and carries out the same order. In the eye, the iris sphincter contracts so the pupil narrows, and the ciliary muscle tightens, pulling the tissue of the angle with it and opening the drainage channels, so trapped fluid escapes and the pressure falls, which is the point in an angle-closure attack. In the mouth it stimulates the salivary glands to secrete more. The same muscles and glands exist in the airways, gut and skin, and from this come its general side effects.'
  },
  effects: {
    ar: 'من القطرة: رؤية معتمة أو مشوّشة، ولسع أو حرقة أو انزعاج في العين، وحكّة أو احمرار، ودمع أو تورّم، وصداع من شدّ العضلة الهدبية. والحدقة الضيّقة تجعل الدنيا أظلم مما هي، فتصعب الرؤية ليلاً أو في الضوء الخافت. ومن القرص المبلوع: تعرّق غزير وهو أشهرها، وغثيان وقيء وإسهال وحرقة معدة وألم بطن، وسيلان أنف، وقشعريرة وتورّد، وكثرة تبوّل، ودوخة وضعف وصداع، وتورّم الأطراف. والتعرّق الغزير قد يُجفّف الجسم فيلزم شرب كافٍ.',
    en: 'From the drop: dim or blurred vision, stinging, burning or discomfort in the eye, itching or redness, watering or swelling, and headache from the tightened ciliary muscle. A narrowed pupil makes the world darker than it is, so seeing at night or in low light becomes difficult. From the swallowed tablet: heavy sweating, which is the best known, along with nausea, vomiting, diarrhoea, heartburn and abdominal pain, a runny nose, chills and flushing, frequent urination, dizziness, weakness and headache, and swelling of the limbs. Heavy sweating can dehydrate the body, so enough fluid must be drunk.'
  },
  warning: {
    ar: 'اطلب طبيب العيون فوراً إذا رأيت ومضات ضوء مفاجئة أو عوّامات كثيرة جديدة أو ستارة أو فقداناً في جزء من الرؤية، فهذه علامات انفصال شبكية وقد ارتبط البيلوكاربين بهذا الخطر. واطلب المساعدة العاجلة عند تعرّق شديد مع غثيان وقيء وإسهال، فهي علامات فرط التنبيه الكوليني. ومن القرص: اتصل بطبيبك فوراً عند تغيّر الرؤية أو تسارع النبض أو تباطؤه. ولا تقُد ليلاً ولا في ضوء خافت ما دامت الرؤية معتمة. وأخبر طبيبك إن سبق أن أصابك التهاب قزحية حادّ أو انفصال شبكية.',
    en: 'See an eye doctor at once if you see sudden flashes of light, many new floaters, a curtain, or loss of part of the field of vision: these are signs of retinal detachment, and pilocarpine has been linked with that risk. Seek urgent help for heavy sweating with nausea, vomiting and diarrhoea, which are signs of excessive cholinergic stimulation. From the tablet: contact your doctor at once for changes in vision or a fast or slow heartbeat. Do not drive at night or in dim light while vision is dim. Tell your doctor if you have ever had acute iritis or a retinal detachment.'
  },
  interact: {
    ar: 'أخبر طبيبك وصيدليك بكل ما تأخذه، فالنشرة تنصّ على أن جرعات أدوية أخرى قد تحتاج تعديلاً أو مراقبة عن قرب. والمنطق الذي يُفهم منه التعارض هو أن البيلوكاربين ينبّه الجهاز نظير الودّي: فما يعمل مثله كأدوية الزهايمر المثبّطة للكولين إستراز يجمع الأثر ويزيد البطء والتعرّق والمغص، وما يعاكسه من مضادّات الكولين كأدوية المثانة وبعض مضادّات الحساسية ومضادّات الاكتئاب القديمة يُبطل فائدته. وحاصرات بيتا مع القرص المبلوع تزيد احتمال بطء القلب واضطراب التوصيل.',
    en: 'Tell your doctor and pharmacist everything you take, since the leaflet states that other medicines may need their doses changed or need close monitoring. The logic behind the interactions is that pilocarpine stimulates the parasympathetic system: anything that works the same way, such as the cholinesterase inhibitors used in Alzheimer disease, adds to the effect and increases slowing, sweating and cramping, while anticholinergics that oppose it, such as bladder medicines, some antihistamines and older antidepressants, cancel its benefit. Beta-blockers taken with the tablet raise the chance of a slow heart and conduction problems.'
  },
  avoid: {
    ar: 'لا يُستعمل عند التحسّس منه، ولا في الربو غير المنضبط، ولا في التهاب القزحية الحادّ، ولا في أنواع من الزرق يمنعه فيها الطبيب. ويُحسب حسابه في التهاب الشعب المزمن والانسداد الرئوي المزمن لأنه يُضيّق القصبات، وفي حصى الكلى وحصى المرارة ومرض المرارة والكبد، وفي مرض القلب، وفي المرض النفسي. ومن له تاريخ انفصال شبكية يخبر طبيبه قبل البدء. والقرص قد يُنقص الخصوبة عند الجنسين بحسب النشرة. وفي الحمل والرضاعة يُستشار الطبيب. ولا تُقطَّر القطرة والعدسات اللاصقة في العين.',
    en: 'It is not used in anyone allergic to it, in uncontrolled asthma, in acute iritis, or in the forms of glaucoma in which the doctor forbids it. It is weighed carefully in chronic bronchitis and chronic obstructive pulmonary disease because it narrows the airways, in kidney and gallbladder stones and in gallbladder and liver disease, in heart disease, and in mental illness. Anyone with a history of retinal detachment tells their doctor before starting. The tablet may reduce fertility in both sexes according to the leaflet. In pregnancy and breastfeeding a doctor is consulted. The drop is not instilled while contact lenses are in the eye.'
  },
  updated: '2026-09-10',
  src: [
    'https://medlineplus.gov/druginfo/meds/a682874.html',
    'https://medlineplus.gov/druginfo/meds/a608039.html'
  ]
};

/* ── ٥) الأسيتازولاميد ────────────────────────────────────── */
RX_BODY['acetazolamide'] = {
  what: {
    ar: 'الأسيتازولاميد قرص أو كبسولة تُبلع، وهو مثبّط لإنزيم الكربونيك أنهيدراز ويُصنّف كذلك مُدرّاً للبول. وهو دواء قديم متعدّد الأبواب: يعمل في العين وفي الكلية وفي الدماغ وفي مركز التنفّس، ولذلك تجده عند طبيب العيون وطبيب الأعصاب ومسافر الجبال العالية في آنٍ واحد. وبنيته الكيميائية من عائلة السلفوناميدات، وهذه نقطة مهمّة لمن عنده حساسية من أدوية السلفا. ويُصرف بوصفة، وله شكل ممتدّ الأثر.',
    en: 'Acetazolamide is a swallowed tablet or capsule, an inhibitor of the enzyme carbonic anhydrase and also classed as a diuretic, a water pill. It is an old drug with many doors: it works in the eye, the kidney, the brain and the breathing centre, which is why it turns up with the eye doctor, the neurologist and the high-altitude traveller alike. Its chemistry belongs to the sulfonamide family, an important point for anyone allergic to sulfa drugs. It is prescription-only and comes in an extended-release form as well.'
  },
  why: {
    ar: 'يُوصف في الزرق لخفض ضغط العين، وخاصةً حين لا تكفي القطرات أو في النوبة الحادّة. ويُستعمل لتخفيف شدّة داء المرتفعات ومدّته، وهو الاضطراب الذي يصيب الصاعد سريعاً إلى ارتفاع عالٍ فيشكو اضطراب معدة وصداعاً وضيق نفس ودوخة ونعاساً وإرهاقاً. ويُعطى مع أدوية أخرى لإنقاص الوذمة أي احتباس السوائل، ولضبط النوبات في أنواع من الصرع. ويُستعمل كذلك في ارتفاع الضغط داخل الجمجمة مجهول السبب لتقليل إفراز السائل الدماغي الشوكي.',
    en: 'It is prescribed in glaucoma to lower eye pressure, especially when drops are not enough or in an acute attack. It is used to reduce the severity and duration of altitude sickness, the disorder that strikes someone who climbs quickly to a high elevation and brings an upset stomach, headache, shortness of breath, dizziness, drowsiness and fatigue. It is given with other medicines to reduce oedema, that is fluid retention, and to help control seizures in certain types of epilepsy. It is also used in idiopathic intracranial hypertension to cut the production of cerebrospinal fluid.'
  },
  how: {
    ar: 'الكربونيك أنهيدراز إنزيم يُسرّع تحويل ثاني أكسيد الكربون والماء إلى بيكربونات وحمض، وهذا التفاعل هو الذي يُحرّك الماء والأملاح في مواضع كثيرة من الجسم. فتثبيطه في الجسم الهدبي داخل العين يُقلّل إفراز السائل المائي فينزل ضغط العين. وتثبيطه في الكلية يمنع إعادة امتصاص البيكربونات فيخرج مع البول ومعه ماء، فيزيد الإدرار ويصير الدم أميل إلى الحموضة. وهذه الحموضة الخفيفة نفسها هي التي تنفع في الجبل: تُنبّه مركز التنفّس فيتنفّس الصاعد أعمق وأسرع فيتأقلم أبكر.',
    en: 'Carbonic anhydrase is an enzyme that speeds the conversion of carbon dioxide and water into bicarbonate and acid, and that reaction is what moves water and salts in many places in the body. Inhibiting it in the ciliary body inside the eye reduces the secretion of aqueous fluid, so eye pressure falls. Inhibiting it in the kidney prevents bicarbonate being reabsorbed, so it leaves in the urine and carries water with it, increasing urine output and tipping the blood slightly towards acid. That same mild acidity is what helps on the mountain: it stimulates the breathing centre, so the climber breathes deeper and faster and acclimatises sooner.'
  },
  effects: {
    ar: 'أشيع ما يُحسّ به تنميل ووخز في الأصابع واليدين والقدمين وحول الفم، وهو شائع جداً ومزعج لكنه ليس خطراً بذاته. ويأتي اضطراب معدة وقيء وفقد شهية، وتغيّر مذاق الأشياء وخاصةً المشروبات الغازية فيصير طعمها معدنياً غريباً. وكثرة التبوّل وزيادة العطش متوقّعتان لأنه مُدرّ. ونعاس وصداع وإرهاق، وقد يزيد النعاس مع الكحول. وقد يجعل الجلد أكثر حساسية لأشعة الشمس فيلزم واقٍ ولباس ساتر.',
    en: 'The commonest sensation is numbness and tingling in the fingers, hands, feet and around the mouth, very common and unpleasant but not in itself dangerous. There is stomach upset, vomiting and loss of appetite, and a change in how things taste, especially fizzy drinks, which acquire a strange metallic flavour. Frequent urination and increased thirst are expected, since it is a diuretic. Drowsiness, headache and fatigue occur, and drowsiness increases with alcohol. It can make the skin more sensitive to sunlight, so sunscreen and covering clothing are needed.'
  },
  warning: {
    ar: 'توقّف واتصل بطبيبك فوراً عند طفح جلدي أو حمّى أو التهاب حلق أو قشعريرة، فالسلفوناميدات قد تُحدث تفاعلاً جلدياً شديداً أو تُنقص كريات الدم. واطلب الطوارئ عند نزف أو تكدّم غير معتاد، أو اصفرار الجلد وبياض العين، أو تشنّج، أو تخليط ذهني. وراجع طبيبك بلا تأخير عند دم في البول أو ألم عند التبوّل أو ألم خاصرة، فقد يُكوّن حصى في الكلى. والتنميل الشديد مع ضعف عضلي أو خفقان قد يعني اضطراب أملاح، وهو يُنقص البوتاسيوم. ولا تقُد إن كنت ناعساً.',
    en: 'Stop and contact your doctor at once for a skin rash, fever, sore throat or chills, since sulfonamides can cause a severe skin reaction or lower the blood cells. Seek emergency help for unusual bleeding or bruising, yellowing of the skin and the whites of the eyes, a seizure, or confusion. See your doctor without delay for blood in the urine, pain on passing urine or flank pain, as it can form kidney stones. Severe tingling with muscle weakness or palpitations may mean a salt disturbance, since it lowers potassium. Do not drive if you feel drowsy.'
  },
  interact: {
    ar: 'تُسمّي النشرة أدوية بعينها يجب أن تُذكر للطبيب: الأسبرين وجرعاته العالية بوجه خاص لأن الجمع قد يُسمّم، والديفلونيزال، والليثيوم، والديجوكسين، والسيكلوسبورين، والمنبّهات الأمفيتامينية، والفينوباربيتال والبريميدون، وأدوية الاكتئاب وأدوية نظم القلب، والمدرّات الأخرى، والفيتامينات. والمنطق العامّ أنه يُنقص البوتاسيوم فيزيد خطر الديجوكسين واضطراب النظم، ويُغيّر حموضة البول فيُبطئ أو يُسرّع خروج أدوية أخرى. والكحول يزيد النعاس. وأخبر أي طبيب أو جرّاح أنك تأخذه قبل أي عملية.',
    en: 'The leaflet names specific medicines that must be mentioned to the doctor: aspirin, high doses in particular, because the combination can be toxic, diflunisal, lithium, digoxin, ciclosporin, amphetamine stimulants, phenobarbital and primidone, medicines for depression and for heart rhythm, other diuretics, and vitamins. The general logic is that it lowers potassium, increasing the danger of digoxin and of rhythm disturbance, and that it changes the acidity of the urine, so other drugs leave the body faster or slower. Alcohol adds to drowsiness. Tell any doctor or surgeon you take it before an operation.'
  },
  avoid: {
    ar: 'لا يأخذه من تحسّس من الأسيتازولاميد أو من أدوية السلفا أو من المدرّات. ويُنبَّه عليه بشدّة في مرض الكلى وفي مرض الكبد، لأنه يُغيّر أملاح الدم وحموضته وقد يُفاقم اعتلال الدماغ الكبدي، وفي مرض القلب، وفي السكّري. ويُخبَر الطبيب عن كل مرض سابق قبل البدء. وفي الحمل يُستشار الطبيب قبل الاستعمال ويُتصل به فوراً عند حدوث حمل أثناء العلاج، وكذلك في الرضاعة. ومن يصعد الجبال يذكر أن الدواء لا يُغني عن الصعود المتدرّج ولا عن النزول عند اشتداد الأعراض.',
    en: 'It must not be taken by anyone allergic to acetazolamide, to sulfa drugs or to diuretics. Strong caution applies in kidney disease and in liver disease, because it alters the blood salts and acidity and can worsen liver-related brain impairment, and in heart disease and diabetes. Every previous illness should be told to the doctor before starting. In pregnancy a doctor is consulted before use and contacted at once if pregnancy occurs during treatment, and the same applies in breastfeeding. Anyone climbing should remember that the drug does not replace a gradual ascent, nor descent when symptoms worsen.'
  },
  updated: '2026-09-10',
  src: [
    'https://medlineplus.gov/druginfo/meds/a682756.html'
  ]
};

/* ── ٦) التتراكايين ───────────────────────────────────────── */
RX_BODY['tetracaine'] = {
  what: {
    ar: 'التتراكايين مخدّر موضعي من مجموعة الإسترات الأمينية، وأشهر صوره قطرة عين تُخدّر سطح القرنية والملتحمة دقائق معدودة. وتضعه منظمة الصحة العالمية في قائمة الأدوية الأساسية لرخصه وفائدته. وله صور أخرى: محلول للتخدير الشوكي، ومستحضر جلدي يُخلط أحياناً مع الليدوكايين قبل إجراءات الليزر. وأهمّ ما يجب أن يُعرف عنه أن قطرة العين دواء عيادة لا دواء بيت: تُستعمل مرّة تحت يد الطبيب ولا تُصرف ليأخذها المريض معه.',
    en: 'Tetracaine is a local anaesthetic of the amino-ester group, best known as an eye drop that numbs the surface of the cornea and conjunctiva for a few minutes. The World Health Organization lists it as an essential medicine for its low cost and usefulness. It has other forms: a solution for spinal anaesthesia, and a skin preparation sometimes mixed with lidocaine before laser procedures. The most important thing to know is that the eye drop is a clinic medicine, not a home medicine: it is used once in the doctor’s hands and is not dispensed for the patient to take away.'
  },
  why: {
    ar: 'يُستعمل في العيادة لتخدير سطح العين قبل إجراءات قصيرة: قياس ضغط العين بجهاز التماس، ونزع جسم غريب من القرنية أو الملتحمة، وإزالة حلقة الصدأ، وفحص القرنية بالصبغة عند شدّة الألم والتشنّج الجفني، ووضع العدسات التشخيصية. ويُستعمل كذلك في التخدير الشوكي وفي إجراءات جلدية. وقد يُستعمل خارج النشرة لتخفيف ألم خدش القرنية أو قبل تركيب قسطرة وريدية عند الأطفال. وليس له دور علاجي إطلاقاً: هو يُسكت الألم لحظة الإجراء ولا يشفي شيئاً.',
    en: 'It is used in the clinic to numb the surface of the eye before short procedures: measuring eye pressure with a contact tonometer, removing a foreign body from the cornea or conjunctiva, removing a rust ring, examining the cornea with dye when pain and lid spasm are severe, and placing diagnostic lenses. It is also used in spinal anaesthesia and in skin procedures. Off-label it may be used to ease the pain of a corneal abrasion or before inserting an intravenous line in children. It has no therapeutic role at all: it silences pain for the moment of the procedure and heals nothing.'
  },
  how: {
    ar: 'ينقل العصب إشارة الألم بموجة كهربائية تعتمد على دخول الصوديوم إلى داخل الليف العصبي عبر قنوات في غشائه. يعبر التتراكايين الغشاء وهو غير متأيّن، ثم يتأيّن داخل الخلية ويرتبط بالوحدة ألفا من قناة الصوديوم فيسدّها من الداخل. وحين تُسدّ القنوات في ثلاث عقد متتالية من عقد رانفييه يعجز العصب عن نقل الإشارة، فلا يصل الألم إلى الدماغ رغم أن السبب باقٍ. وهذا يعني أن الإحساس الواقي للعين يُلغى: يغيب المنعكس الذي يجعلك تُغمض وتدمع إذا مسّ عينك شيء.',
    en: 'A nerve carries a pain signal as an electrical wave that depends on sodium entering the nerve fibre through channels in its membrane. Tetracaine crosses the membrane in its uncharged form, then becomes charged inside the cell and binds to the alpha subunit of the sodium channel, blocking it from within. When the channels are blocked at three successive nodes of Ranvier, the nerve can no longer carry the signal, so pain does not reach the brain although its cause remains. This means the eye’s protective sensation is switched off: the reflex that makes you blink and tear when something touches the eye disappears.'
  },
  effects: {
    ar: 'أشيع ما يُحسّ لسع أو حرقة قوية لحظة التقطير تزول في ثوانٍ، ثم خدر وضبابية خفيفة في الرؤية تدوم دقائق. وقد يحمرّ سطح العين. والتحسّس منه أكثر منه في مجموعة الأميدات، وسببه ناتج استقلابه المسمّى حمض بارا أمينو بنزويك، والمادّة الحافظة ميثيل بارابين تُنتج الناتج نفسه فيلزم قراءة المكوّنات. وأما الآثار العامّة فلا تحدث من قطرة العين المفردة عملياً، لكنها معروفة من الأشكال الأخرى: خدر حول الفم وطنين وتشوّش رؤية ودوخة، ثم تشنّج وهبوط قلبي في التسمّم.',
    en: 'What is felt most is a strong sting or burn at the moment of instillation, gone in seconds, followed by numbness and slight blurring of vision lasting minutes. The eye surface may redden. Allergy to it is more frequent than with the amide group, and its cause is its breakdown product para-aminobenzoic acid; the preservative methylparaben yields the same product, so the ingredients must be read. General effects practically do not occur from a single eye drop, but they are known from the other forms: numbness around the mouth, ringing in the ears, blurred vision and dizziness, then seizures and cardiac collapse in poisoning.'
  },
  warning: {
    ar: 'الخطر الأكبر ليس في القطرة الواحدة بل في تكرارها: الاستعمال المطوّل أو المتكرّر في البيت يُتلف خلايا سطح القرنية ويمنعها من الالتئام، فتظهر عتامة القرنية وارتشاحات عميقة وقرحة، وقد تنثقب القرنية ويُفقد البصر فقداناً لا يعود. وقد وُصفت عتامة وضعف رؤية شديد بعد قطرتين فقط عند شخص. ولذلك لا تُصرف هذه القطرة للاستعمال المنزلي، والأكاديمية الأمريكية لطبّ العيون لا تُقرّها وصفةً روتينية لخدش القرنية. واطلب الطوارئ عند تشوّش رؤية متفاقم أو ألم متزايد أو احمرار شديد بعد استعمالها.',
    en: 'The greater danger is not in one drop but in repeating it: prolonged or repeated use at home damages the surface cells of the cornea and stops them healing, so corneal opacity, deep infiltrates and ulceration appear, the cornea may perforate and sight can be lost irreversibly. Opacity and severe visual loss have been described after only two drops in one person. For this reason the drop is not dispensed for home use, and the American Academy of Ophthalmology does not endorse it as a routine prescription for corneal abrasion. Seek emergency care for worsening blurred vision, increasing pain or severe redness after its use.'
  },
  interact: {
    ar: 'ناتج استقلابه حمض بارا أمينو بنزويك يُثبّط عمل المضادّات الحيوية السلفوناميدية، فلا يُتوقّع أثرها الكامل مع استعماله. وتزيد المؤكسدات خطر ميتهيموغلوبين الدم معه، ومنها النتروغليسرين ونتروبروسيد الصوديوم وأكسيد النيتروز، وهذه حالة يعجز فيها الدم عن حمل الأكسجين فيزرقّ اللون رغم كفاية التنفّس. ويُحسب مجموع كل المخدّرات الموضعية المُعطاة في الجلسة الواحدة لأن سميّتها تتراكم، ويُذكر بوجه خاص البوبيفاكايين الشحمي لأن أثره يمتدّ طويلاً بعد إعطائه.',
    en: 'Its breakdown product para-aminobenzoic acid inhibits the action of sulfonamide antibiotics, so their full effect should not be expected alongside it. Oxidising agents increase the risk of methaemoglobinaemia with it, among them nitroglycerin, sodium nitroprusside and nitrous oxide; this is a state in which the blood cannot carry oxygen, so the colour turns blue despite adequate breathing. The total of all local anaesthetics given in a single session must be counted, because their toxicity accumulates, and liposomal bupivacaine is specifically noted because its effect lasts long after it is given.'
  },
  avoid: {
    ar: 'لا يُستعمل عند تاريخ تحسّس شديد من المخدّرات الموضعية الإسترية أو من حمض بارا أمينو بنزويك أو من البارابين، ولا في موضع فيه عدوى نشطة، ولا مع هبوط ضغط غير منضبط في الأشكال الجهازية. ولا يُعطى للمريض ليحمله معه إلى البيت مهما اشتدّ الألم. ومن قُطّرت له العين لا يفركها ولا يضع عدسة لاصقة حتى يعود الإحساس كاملاً، لأن العين المخدّرة لا تحمي نفسها فتتخدّش بلا أن يشعر. ويُغطّى العين أحياناً حتى يزول الأثر. وفي الحمل والرضاعة يُستعمل بقرار الطبيب.',
    en: 'It is not used in anyone with a history of severe allergy to ester local anaesthetics, to para-aminobenzoic acid or to parabens, nor at a site of active infection, nor with uncontrolled low blood pressure in the systemic forms. It is not given to a patient to take home however severe the pain. Anyone whose eye has been anaesthetised must not rub it or insert a contact lens until sensation fully returns, because a numb eye does not protect itself and gets scratched without being felt. The eye is sometimes covered until the effect wears off. In pregnancy and breastfeeding it is used by the doctor’s decision.'
  },
  updated: '2026-09-10',
  src: [
    'https://www.ncbi.nlm.nih.gov/books/NBK535437/',
    'https://pmc.ncbi.nlm.nih.gov/articles/PMC9806309/',
    'https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=01fba5f8-a60a-444c-9abd-299540b8815a'
  ]
};

/* ── ٧) التروبيكاميد ──────────────────────────────────────── */
RX_BODY['tropicamide'] = {
  what: {
    ar: 'التروبيكاميد محلول قطرة عين مضادّ للكولين، يُصنّف موسّعاً للحدقة وشالّاً للمطابقة. وهو أكثر موسّعات الحدقة استعمالاً في العيادات لأنه قويّ الأثر سريع البدء قصير المدّة قليل المضاعفات، فيوسّع الحدقة ثم يتركها تعود من نفسها في ساعات قليلة، بخلاف الأتروبين الذي يبقى أثره أياماً. ويأتي بقوّتين: الأضعف يوسّع الحدقة مع شلل مطابقة يسير، والأقوى يشلّ المطابقة شللاً كاملاً فيُستعمل حين يُراد قياس النظر بلا تدخّل من عضلة العين.',
    en: 'Tropicamide is an anticholinergic eye-drop solution, classed as a mydriatic and cycloplegic. It is the most used pupil dilator in clinics because it is powerful, fast in onset, short in duration and low in complications: it widens the pupil and then lets it return on its own within a few hours, unlike atropine whose effect lasts days. It comes in two strengths: the weaker dilates the pupil with slight paralysis of accommodation, the stronger paralyses accommodation completely and is used when refraction must be measured without the eye muscle interfering.'
  },
  why: {
    ar: 'يُستعمل لغرض تشخيصي في المقام الأول: توسيع الحدقة ليرى الطبيب قاع العين والشبكية والعصب البصري والعدسة، وهذا لا يمكن من خلال حدقة ضيّقة. ومن أهمّ دواعيه فحص الشبكية عند مريض السكّري بحثاً عن اعتلال الشبكية السكري قبل أن يُفقد البصر، وفحص العين قبل جراحة الساد وبعدها، والبحث عن تمزّق أو انفصال في الشبكية عند من يشكو ومضات وعوّامات. ويُستعمل كذلك لشلّ المطابقة عند قياس نظر الأطفال، وقبل بعض عمليات العين وبعدها.',
    en: 'It is used first of all for diagnosis: widening the pupil so the doctor can see the back of the eye, the retina, the optic nerve and the lens, none of which can be seen through a narrow pupil. Among its most important indications is examining the retina of a diabetic patient in search of diabetic retinopathy before sight is lost, examining the eye before and after cataract surgery, and looking for a tear or detachment of the retina in someone complaining of flashes and floaters. It is also used to paralyse accommodation when measuring children’s refraction, and before and after some eye operations.'
  },
  how: {
    ar: 'حجم الحدقة تحكمه عضلتان متعاكستان في القزحية: عضلة مضيّقة يقودها الجهاز نظير الودّي بناقل الأسيتيل كولين، وعضلة موسّعة يقودها الجهاز الودّي. يحجب التروبيكاميد مستقبلات الأسيتيل كولين المسكارينية فيُسكت أمر التضييق، فتغلب العضلة الموسّعة وتتّسع الحدقة. ويحجب المستقبلات نفسها في العضلة الهدبية التي تُغيّر شكل العدسة للرؤية القريبة، فتُشلّ المطابقة ويصير القريب ضبابياً. ويبلغ التوسّع ذروته بعد نحو نصف ساعة، ويزول عادةً خلال ساعات وقد يمتدّ إلى اليوم التالي عند بعض الناس.',
    en: 'Pupil size is governed by two opposing muscles in the iris: a constrictor driven by the parasympathetic system through the messenger acetylcholine, and a dilator driven by the sympathetic system. Tropicamide blocks the muscarinic acetylcholine receptors and silences the order to constrict, so the dilator prevails and the pupil widens. It blocks the same receptors in the ciliary muscle that changes the lens shape for near vision, so accommodation is paralysed and close objects blur. Dilation peaks about half an hour later and usually fades within hours, though in some people it lasts into the next day.'
  },
  effects: {
    ar: 'أكثر ما يُحسّ لسع عابر عند التقطير، ثم حساسية شديدة للضوء لأن الحدقة المتّسعة لا تستطيع أن تُضيّق، وتشوّش في الرؤية القريبة يمنع القراءة والنظر إلى الشاشة. وقد يرتفع ضغط العين ارتفاعاً عابراً. والآثار العامّة نادرة مع القطرة لكنها موصوفة: جفاف الفم وحرارة وإمساك وتسارع نبض وصداع، وتكثر عند الأطفال الصغار وكبار السنّ. وسُجّلت نادراً اضطرابات في الجهاز العصبي المركزي شملت تفاعلات ذهانية ومشكلات سلوكية، وأكثر ما ذُكر ذلك عند الأطفال.',
    en: 'What is felt most is a transient sting on instillation, then strong sensitivity to light because a widened pupil cannot narrow, and blurred near vision that prevents reading or looking at a screen. Eye pressure may rise transiently. General effects are rare with the drop but are described: dry mouth, fever, constipation, a fast pulse and headache, and they are more frequent in young children and the elderly. Central nervous system disturbances have rarely been recorded, including psychotic reactions and behavioural problems, most often reported in children.'
  },
  warning: {
    ar: 'اطلب طبيب العيون فوراً إذا جاءك بعد التقطير ألم شديد في العين مع احمرار وصداع وغثيان وقيء ورؤية هالات حول الأضواء، فهذه أعراض نوبة زرق انسداد الزاوية، وهي حالة تُفقد البصر إن تأخّرت. ولا تقُد ولا تشغّل آلة ما دامت الحدقة متّسعة والرؤية القريبة ضبابية، واحمل نظّارة شمسية معك للفحص. ولا يوجد اليوم دواء معتمد يعكس أثره، والبيلوكاربين لا يفيد في عكسه، فالانتظار هو الحلّ. وراجع الطبيب فوراً عند تغيّر سلوك الطفل أو تخليطه بعد القطرة.',
    en: 'See an eye doctor at once if after the drop you get severe eye pain with redness, headache, nausea, vomiting and haloes around lights, since these are the symptoms of an angle-closure glaucoma attack, which costs sight if delayed. Do not drive or operate machinery while the pupil is wide and near vision blurred, and take sunglasses with you to the appointment. There is today no approved medicine that reverses its effect, and pilocarpine does not reverse it, so waiting is the answer. See a doctor at once if a child’s behaviour changes or they become confused after the drop.'
  },
  interact: {
    ar: 'ليس له تعارض جهازي مشهور لأن ما يُمتصّ منه قليل، لكن المنطق الدوائي يوجب الحذر: كل ما يعمل عمله من مضادّات الكولين، كأدوية فرط نشاط المثانة ومضادّات الحساسية القديمة ومضادّات الاكتئاب ثلاثية الحلقات وبعض أدوية باركنسون، يجمع الأثر فيزيد جفاف الفم والإمساك وتسارع النبض وتشوّش الذهن عند كبار السنّ. وما يعاكسه من الأدوية الكولينية كالبيلوكاربين ومثبّطات الكولين إستراز يُنقص أثره. والضغط بالإصبع على الزاوية الداخلية للعين بعد التقطير يُقلّل ما يدخل الدم.',
    en: 'It has no famous systemic interaction because little of it is absorbed, but pharmacological logic calls for care: anything that works the same way among the anticholinergics, such as overactive bladder medicines, older antihistamines, tricyclic antidepressants and some Parkinson drugs, adds to the effect and increases dry mouth, constipation, a fast pulse and confusion in the elderly. Cholinergic medicines that oppose it, such as pilocarpine and cholinesterase inhibitors, reduce its effect. Pressing a finger on the inner corner of the eye after instillation reduces how much enters the blood.'
  },
  avoid: {
    ar: 'لا يُستعمل عند التحسّس من التروبيكاميد أو من أي من مكوّنات المحلول. ولا يُستعمل في زرق انسداد الزاوية الحادّ حتى تُعمل فتحة قزحية بالليزر، ويُحسب حسابه عند من زاويته ضيّقة تشريحياً وإن كان وقوع النوبة قليلاً. ويُحذَر في الخدّج والرضّع لأن الامتصاص العامّ عندهم أعلى، وفي كبار السنّ الذين عندهم عوامل خطر قلبية وعائية. ويُحفظ بعيداً عن متناول الأطفال. وهو من الفئة سي في الحمل ولا يُعرف مقدار خروجه في حليب الأم. وتُنزع العدسات اللاصقة قبل التقطير.',
    en: 'It is not used in anyone allergic to tropicamide or to any ingredient of the solution. It is not used in acute angle-closure glaucoma until a laser opening has been made in the iris, and caution applies to anyone with an anatomically narrow angle, even though an attack is uncommon. Care is needed in premature and newborn infants because systemic absorption is higher in them, and in elderly people with cardiovascular risk factors. It is kept out of the reach of children. It is pregnancy category C and its passage into breast milk is unknown. Contact lenses are removed before instillation.'
  },
  updated: '2026-09-10',
  src: [
    'https://www.ncbi.nlm.nih.gov/books/NBK541069/',
    'https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=57165763-29dc-4812-b840-a8a5086416f3'
  ]
};

/* ── ٨) الفلوريسين ────────────────────────────────────────── */
RX_BODY['fluorescein'] = {
  what: {
    ar: 'الفلوريسين صبغة تشخيصية فلورية لا دواء علاجياً: لا يقتل جرثومة ولا يخفض ضغطاً ولا يسكّن ألماً، وظيفته الوحيدة أن يُظهر ما لا تراه العين المجرّدة. يأتي شريطاً ورقياً مشبعاً بالصبغة يُبلّل بمحلول ملحي ويُلمس به سطح العين، ويأتي محلولاً مشتركاً مع مخدّر موضعي، ويأتي محلولاً للحقن الوريدي في تصوير الأوعية. وشرائط العين منها ما لم تُقرّ إدارة الغذاء والدواء الأمريكية سلامته وفعاليّته رسمياً ولم تعتمد نشرته، وهذا مذكور على اللصاقة نفسها.',
    en: 'Fluorescein is a fluorescent diagnostic dye, not a therapeutic drug: it kills no germ, lowers no pressure and relieves no pain; its only job is to show what the naked eye cannot see. It comes as a paper strip soaked in dye, moistened with saline and touched to the eye surface, as a solution combined with a topical anaesthetic, and as a solution for intravenous injection in angiography. Some of the eye strips have not been found safe and effective by the American Food and Drug Administration and their labelling is not approved, which is stated on the label itself.'
  },
  why: {
    ar: 'يُستعمل موضعياً لكشف خدوش القرنية وقرحها والأجسام الغريبة عليها، ولقياس ضغط العين بجهاز التماس، ولتقييم ثبات الغشاء الدمعي في جفاف العين بقياس زمن تفكّك الطبقة الدمعية، ولضبط تركيب العدسات اللاصقة. ويُحقن وريدياً لتصوير أوعية الشبكية والمشيمية والقزحية، وهو الفحص الذي يكشف تسرّب الأوعية في اعتلال الشبكية السكري والتنكّس البقعي وانسداد أوعية الشبكية. ويُستعمل في الجراحة لتمييز الأنسجة والأعصاب وتقييم تروية النسيج.',
    en: 'Topically it is used to reveal corneal scratches, ulcers and foreign bodies, to measure eye pressure with a contact tonometer, to assess the stability of the tear film in dry eye by timing how long the tear layer takes to break up, and to check the fit of contact lenses. It is injected into a vein to image the vessels of the retina, choroid and iris, the test that reveals leaking vessels in diabetic retinopathy, macular degeneration and retinal vascular occlusion. In surgery it is used to distinguish tissues and nerves and to assess how well a tissue is perfused.'
  },
  how: {
    ar: 'الفلوريسين مادّة تمتصّ الضوء الأزرق ثم تُعيد إصداره ضوءاً أخضر ساطعاً، وهذه الخاصّية تُسمّى الفلورية. فحين يُسلَّط على العين ضوء أزرق كوبالتي من المصباح الشقّي يتوهّج ما علق فيه الصبغ أخضر لامعاً. وسطح القرنية السليم مغطّى بطبقة دهنية طاردة للصبغة فلا يتلوّن، أما حيث انكشفت الخلايا بخدش أو قرحة فترتبط الصبغة بها وتتسرّب معها السائل، فيرتسم الخدش خريطةً خضراء واضحة الحدود. وفي الحقن الوريدي يجري الصبغ في الأوعية فتُصوَّر كأنها مرسومة.',
    en: 'Fluorescein absorbs blue light and re-emits it as bright green, a property called fluorescence. When cobalt blue light from a slit lamp is shone on the eye, whatever holds the dye glows brilliant green. A healthy corneal surface is covered by an oily layer that repels the dye, so it does not stain; but where cells are exposed by a scratch or an ulcer, the dye bonds to them and leaks with the fluid, so the scratch appears as a green map with sharp edges. Injected into a vein, the dye runs through the vessels so they can be photographed as if drawn.'
  },
  effects: {
    ar: 'من الشرائط والقطرات: لسع وحرقة وتهيّج عابر في العين، ودمع، مع اصفرار مؤقّت في الدمع والجفن. ومن الحقن الوريدي: اصفرار الجلد يزول عادةً في ساعات، وبول أصفر فاقع يصفو خلال يوم أو أكثر بقليل، وغثيان وقيء وتغيّر في المذاق. وقد يحدث التهاب وريد أو ألم في موضع الحقن. والصبغة تلطّخ العدسات اللاصقة اللينة تلطيخاً يبقى، فتُنزع قبل الفحص ولا تُعاد إلا بعد وقت كافٍ. ولا حاجة إلى تحاليل مخبرية للمتابعة بعد الاستعمال.',
    en: 'From strips and drops: stinging, burning and transient irritation of the eye with watering, plus temporary yellowing of the tears and eyelid. From intravenous injection: yellow discolouration of the skin that usually clears within hours, bright yellow urine that clears within a day or a little more, along with nausea, vomiting and a change in taste. Inflammation of the vein or pain at the injection site can occur. The dye stains soft contact lenses permanently, so they are removed before the examination and not replaced until enough time has passed. No laboratory tests are needed for follow-up.'
  },
  warning: {
    ar: 'الخطر الجدّي محصور في الحقن الوريدي لا في الشريط: اطلب المساعدة فوراً عند طفح منتشر أو تورّم الوجه والحلق أو صفير أو ضيق نفس أو دوخة شديدة أو إغماء بعد الحقن، فالتأق وتشنّج القصبات وهبوط الضغط والإغماء وتوقّف القلب مسجّلة وإن كانت نادرة. ومحلول الحقن قلويّ، فتسرّبه خارج الوريد يُحدث أذى نسيجياً شديداً قد يصل إلى تسلّخ الجلد وأذى العصب: أخبر الممرّض فوراً عند ألم أو حرقة أو انتفاخ عند الإبرة. وأما اصفرار الجلد والبول فمتوقّع ولا يستدعي قلقاً.',
    en: 'The serious danger is confined to the intravenous injection, not the strip: seek help at once for a spreading rash, swelling of the face and throat, wheeze, breathlessness, severe dizziness or fainting after the injection, since anaphylaxis, bronchospasm, low blood pressure, fainting and cardiac arrest are recorded, though rare. The injection solution is alkaline, so leakage outside the vein causes severe tissue injury that can reach skin sloughing and nerve damage: tell the nurse at once about pain, burning or swelling at the needle. Yellowing of skin and urine, by contrast, is expected and needs no worry.'
  },
  interact: {
    ar: 'ليس للفلوريسين تعارض دوائي مشهور، لأنه لا يعمل في مستقبل ولا في إنزيم بل يُرى فقط. والتنبيه العملي أنه يُخلط أحياناً في قنّينة واحدة مع مخدّر موضعي مثل البينوكسينات، فتنطبق على تلك التركيبة تحذيرات المخدّر الموضعي كاملة لا تحذيرات الصبغة وحدها. وقد يُشوّش وجود الصبغة في الدم على بعض التحاليل المخبرية وعلى قراءة مقياس تشبّع الأكسجين لفترة قصيرة بعد الحقن، فيُخبَر المختبر بأن الفحص أُجري. وأخبر طبيبك بكل ما تأخذه قبل تصوير الأوعية.',
    en: 'Fluorescein has no famous drug interaction, because it does not act on a receptor or an enzyme; it is only seen. The practical point is that it is sometimes mixed in one bottle with a topical anaesthetic such as benoxinate, in which case the full warnings of that anaesthetic apply to the combination, not the warnings of the dye alone. The presence of the dye in the blood may briefly disturb some laboratory tests and the reading of a pulse oximeter after injection, so the laboratory should be told the test was done. Tell your doctor everything you take before angiography.'
  },
  avoid: {
    ar: 'لا يُعطى لمن سبق أن تحسّس من الفلوريسين بأي من صوره، وهذا منع مطلق. ويُتحرّى بحذر عند من عنده ربو أو تاريخ حساسية شديدة، لأن احتمال التفاعل عندهم أعلى، ويُهيّأ لهم ما يلزم قبل الحقن. وتُنزع العدسات اللاصقة قبل الوضع الموضعي منعاً للتلطيخ الدائم. وفي الحمل البيانات محدودة فلا يُستعمل إلا حين تُبرّر الفائدة الخطر، وهو يظهر في حليب الأم بمقدار أكبر بعد الحقن منه بعد الاستعمال الموضعي، ويُنصح بتجنّب الضوء القويّ مؤقّتاً بعد إعطائه.',
    en: 'It is not given to anyone who has previously reacted to fluorescein in any of its forms, and this is an absolute bar. Careful assessment applies to anyone with asthma or a history of severe allergy, in whom a reaction is more likely, and preparations are made before injecting them. Contact lenses are removed before topical application to prevent permanent staining. In pregnancy the data are limited, so it is used only when the benefit justifies the risk; it appears in breast milk in greater amounts after injection than after topical use, and temporarily avoiding strong light after administration is advised.'
  },
  updated: '2026-09-10',
  src: [
    'https://www.ncbi.nlm.nih.gov/books/NBK555957/',
    'https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=88ced9b3-60af-492b-9aca-1046efed17cb',
    'https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=ebb3883c-71f6-4fd0-a7e6-0ba8e1136dd9'
  ]
};

/* ── ٩) الناتاميسين ───────────────────────────────────────── */
RX_BODY['natamycin'] = {
  what: {
    ar: 'الناتاميسين مضاد فطري من مجموعة البوليينات رباعية الإين، ويأتي معلّقاً أبيض يُقطَّر في العين، أي أن جسيماته لا تذوب في السائل بل تبقى معلّقة فيه، ولهذا تُرجّ القنّينة قبل كل استعمال. وهو الدواء الوحيد المعتمد للاستعمال الموضعي في العين لعلاج التهاب القرنية الفطري، وهذا وحده يجعله دواءً لا بديل جاهزاً عنه. وهو قاتل للفطر في أغلب الحالات ولا أثر له على الجراثيم إطلاقاً، فلا يُستعمل في العدوى البكتيرية.',
    en: 'Natamycin is an antifungal of the tetraene polyene group, supplied as a white suspension instilled into the eye, meaning its particles do not dissolve in the liquid but stay suspended in it, which is why the bottle is shaken before each use. It is the only medicine approved for topical use in the eye to treat fungal keratitis, and that alone makes it a drug with no ready substitute. It is fungicidal in most cases and has no effect whatever on bacteria, so it is not used in bacterial infection.'
  },
  why: {
    ar: 'يُوصف لعلاج العدوى الفطرية في العين: التهاب حافة الجفن الفطري، والتهاب الملتحمة الفطري، والتهاب القرنية الفطري بما فيه الالتهاب بفطر الفوزاريوم الصولاني. وأخطر هذه الثلاثة التهاب القرنية، وهو يصيب غالباً بعد إصابة العين بمادّة نباتية كغصن أو قشّة أو تراب زراعي، أو عند لابس العدسات اللاصقة الذي يُهمل نظافتها. وتنصّ النشرة على أن البدء والاستمرار يُحدَّدان بالتشخيص السريري وبالمسحة والزرع من كشط القرنية وبالاستجابة، لا بالحدس وحده.',
    en: 'It is prescribed for fungal infection of the eye: fungal blepharitis, fungal conjunctivitis, and fungal keratitis including infection with Fusarium solani. The most dangerous of the three is keratitis, which usually follows an eye injury from plant material such as a branch, a piece of straw or agricultural soil, or occurs in a contact lens wearer who neglects lens hygiene. The label states that starting and continuing treatment are determined by the clinical diagnosis, by smear and culture of corneal scrapings, and by the response, not by guesswork alone.'
  },
  how: {
    ar: 'غشاء الخلية الفطرية يحوي مادّة دهنية تُسمّى الإرغوستيرول لا توجد في خلايا الإنسان، وهي التي تحفظ للغشاء تماسكه. يرتبط الناتاميسين بهذه الستيرولات فيخترق الغشاء ويُغيّر نفاذيته، فيصير كالغربال فتنضب من الخلية موادّها الأساسية وتموت. ولأن الإرغوستيرول غائب عن خلايانا فأثره على العين محدود. ولأن جسيماته لا تذوب فهي تبقى على سطح القرنية زمناً أطول وتنفذ إلى داخل العين نفوذاً ضعيفاً، وهذا نافع في العدوى السطحية وقاصر إذا غاص الفطر عميقاً.',
    en: 'The fungal cell membrane contains a fatty substance called ergosterol, absent from human cells, which holds the membrane together. Natamycin binds to these sterols, penetrates the membrane and alters its permeability, so it becomes like a sieve, the cell’s essential contents drain away and it dies. Because ergosterol is absent from our own cells, its effect on the eye is limited. And because its particles do not dissolve, they stay on the corneal surface longer and penetrate poorly into the eye, which is useful in a surface infection and inadequate once the fungus has gone deep.'
  },
  effects: {
    ar: 'تسجّل النشرة من تقارير ما بعد التسويق: انزعاجاً في العين وألماً وتهيّجاً واحتقاناً واحمراراً، ووذمة أي تورّماً، وإحساساً بجسم غريب، ودمعاً، وتغيّراً في الرؤية. وسُجّلت كذلك عتامة في القرنية، وتنميل، وتفاعلات تحسّسية، وألم في الصدر وضيق نفس وإن كانت هذه نادرة جداً مع دواء موضعي. والمعلّق نفسه أبيض كثيف فيترك ضبابية بيضاء على العين بعد كل قطرة تزول بعد قليل، وهذه ليست أثراً جانبياً بل صفة الدواء.',
    en: 'From post-marketing reports the label records: eye discomfort, pain, irritation, hyperaemia and redness, oedema meaning swelling, a foreign body sensation, tearing, and changes in vision. Also recorded are corneal opacity, paraesthesia, allergic reactions, and chest pain and shortness of breath, though these are very rare with a topical medicine. The suspension itself is thick and white, so it leaves a white haze on the eye after each drop which clears shortly, and this is not a side effect but a property of the medicine.'
  },
  warning: {
    ar: 'إن لم تتحسّن العين خلال الأيام الأولى من العلاج فهذه علامة على أن الفطر لا يستجيب أو أن التشخيص غير صحيح، وتنصّ النشرة على إعادة تقييم العلاج عندها لا الاستمرار عليه. وراجع طبيب العيون بلا تأخير إذا ازداد الألم أو الاحمرار، أو اتّسعت البقعة البيضاء على القرنية، أو ظهر صديد داخل العين، أو هبطت الرؤية، أو صارت العين شديدة الحساسية للضوء: التهاب القرنية الفطري يثقب القرنية إن أُهمل. ⛔ للاستعمال الموضعي على العين فقط ولا يُحقن إطلاقاً. ولا يُستعمل إن كانت العبوة متضرّرة.',
    en: 'If the eye has not improved within the first days of treatment, that is a sign the fungus is not responding or the diagnosis is wrong, and the label directs that treatment be re-evaluated rather than continued. See an eye doctor without delay if pain or redness increases, if the white patch on the cornea enlarges, if pus appears inside the eye, if vision falls, or if the eye becomes very sensitive to light: fungal keratitis perforates the cornea if neglected. For topical ophthalmic use only and never for injection. It is not used if the container is damaged.'
  },
  interact: {
    ar: 'لا تُذكر في نشرة الناتاميسين تعارضات دوائية جهازية، لأن ما يُمتصّ منه إلى الدم لا يكاد يُذكر. والتنبيه العملي الأهمّ يخصّ الكورتيزون الموضعي على العين: فهو يخفّف الاحمرار والألم فيوهم بالتحسّن بينما يُطلق الفطر ويسرّع تآكل القرنية، ولذلك لا يُوضع في العدوى الفطرية إلا بقرار طبيب العيون. وإن استُعملت قطرة أخرى مع الناتاميسين فيُترك بينهما فاصل كافٍ. ولا تُلمس رأس القطّارة بأي سطح ولا بالعين، لئلا تتلوّث القنّينة فتُعيد العدوى.',
    en: 'The natamycin label lists no systemic drug interactions, because almost nothing of it is absorbed into the blood. The most important practical warning concerns topical steroid on the eye: it reduces redness and pain and so gives an illusion of improvement while it unleashes the fungus and speeds destruction of the cornea, which is why it is not used in fungal infection except by the eye doctor’s decision. If another drop is used with natamycin, an adequate gap is left between them. The dropper tip is not touched to any surface or to the eye, lest the bottle be contaminated and reseed the infection.'
  },
  avoid: {
    ar: 'لا يُستعمل عند فرط الحساسية لأي من مكوّناته. ولا تُلبس العدسات اللاصقة ما دامت في العين علامات التهاب فطري في الجفن أو الملتحمة أو القرنية، فالعدسة تحبس الفطر على القرنية وتزيد الأذى. وفي الحمل لم تُجرَ دراسات على الحيوان فلا يُستعمل إلا إذا دعت الحاجة إليه بوضوح، وفي الرضاعة لا يُعرف هل يخرج في حليب الأم فيُتوخّى الحذر. ولا يُشارَك الدواء مع غيرك ولا يُستعمل لعين أخرى غير التي وُصف لها، ولا يُحتفظ به لعدوى قادمة.',
    en: 'It is not used in anyone hypersensitive to any of its components. Contact lenses are not worn while there are signs of fungal inflammation in the lid, conjunctiva or cornea, because the lens traps the fungus against the cornea and increases the damage. In pregnancy no animal studies have been carried out, so it is used only if clearly needed, and in breastfeeding it is not known whether it passes into milk, so caution is exercised. The medicine is not shared with anyone else, is not used for an eye other than the one it was prescribed for, and is not kept for a future infection.'
  },
  updated: '2026-09-10',
  src: [
    'https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=2818fcb8-5bac-41fb-864e-3b598308a428',
    'https://www.ncbi.nlm.nih.gov/books/NBK493192/'
  ]
};

/* ── ١٠) التتراسيكلين ─────────────────────────────────────── */
RX_BODY['tetracycline'] = {
  what: {
    ar: 'التتراسيكلين هو الأصل الذي سُمّيت به فصيلة كاملة من المضادّات الحيوية تُعرف بالتتراسيكلينات، ومنها الدوكسيسيكلين والمينوسيكلين اللذان حلّا محلّه في أكثر الاستعمالات لأنهما يبقيان في الجسم أطول ويتأثّران بالطعام أقلّ. ويأتي كبسولةً وقرصاً يُبلعان. وهو مضاد واسع الطيف يوقف تكاثر الجراثيم ولا يقتلها مباشرة، ويشمل طيفه جراثيم لا تصل إليها البنسلينات كالتي تعيش داخل الخلايا. وله كذلك أشكال موضعية للجلد والعين في بعض البلدان.',
    en: 'Tetracycline is the original after which a whole antibiotic class, the tetracyclines, is named, among them doxycycline and minocycline, which have replaced it in most uses because they last longer in the body and are less affected by food. It comes as a swallowed capsule and tablet. It is a broad-spectrum antibiotic that stops bacteria multiplying rather than killing them outright, and its spectrum covers organisms the penicillins cannot reach, such as those living inside cells. It also exists in topical forms for skin and eye in some countries.'
  },
  why: {
    ar: 'يُستعمل لعلاج العدوى الجرثومية، ولعدوى ينقلها القرّاد والقمل والعثّ والحيوان المصاب. ويُستعمل في حبّ الشباب فيقتل الجرثومة التي تُصيب المسامّ ويُنقص كمية الزيت على الجلد، وهذا استعمال يمتدّ شهوراً لا أياماً. ويُوصف أحياناً في داء لايم وفي الملاريا، ويُستعمل للوقاية من الطاعون والتولاريميا بعد التعرّض لهما. وهو من الخيارات المعروفة في الحمّى المالطية والكوليرا والكلاميديا وفي الوردية، وهذه أمراض تشترك في أن الجرثومة فيها حسّاسة لهذه الفصيلة بالذات.',
    en: 'It is used to treat bacterial infections and infections spread by ticks, lice, mites and infected animals. It is used in acne, where it kills the bacterium that infects the pores and lowers the amount of oil on the skin, a use that runs for months rather than days. It is sometimes prescribed in Lyme disease and in malaria, and it is used to prevent plague and tularaemia after exposure. It is among the known options in brucellosis, cholera, chlamydia and rosacea, diseases that share the fact that the responsible organism is sensitive to this class in particular.'
  },
  how: {
    ar: 'تحتاج الجرثومة إلى بناء بروتيناتها لتنمو وتنقسم، وتبنيها في مصنع صغير داخلها يُسمّى الريبوسوم. يدخل التتراسيكلين الخلية الجرثومية ويرتبط بالوحدة الصغرى من ريبوسومها، فيمنع الحمض النووي الريبي الناقل من الالتحام بموضعه، فيتوقّف تركيب البروتين وتعجز الجرثومة عن التكاثر، ويتولّى الجهاز المناعي بقيّة العمل. وريبوسوم خلايانا يختلف في بنيته فلا يتأثّر مثله. وارتباطه الشديد بالكالسيوم هو الذي يُفسّر شيئين معاً: بطلان مفعوله مع الحليب والمضادّات الحمضية، وترسّبه في الأسنان والعظام النامية.',
    en: 'A bacterium needs to build its proteins in order to grow and divide, and it builds them in a small factory inside it called the ribosome. Tetracycline enters the bacterial cell and binds to the small subunit of its ribosome, preventing transfer RNA from docking at its site, so protein assembly stops, the bacterium cannot multiply, and the immune system does the rest. Our own ribosomes differ in structure and are not affected in the same way. Its strong binding to calcium explains two things at once: the loss of its effect with milk and antacids, and its deposition in growing teeth and bones.'
  },
  effects: {
    ar: 'أشيع ما يُشكى منه غثيان وقيء وإسهال، وحكّة في الشرج أو المهبل من فرط نموّ الفطر بعد أن يقتل الدواء جراثيم النبيت الطبيعي، ولسان متورّم أو أسود أو كأنّ عليه شعراً، وحلق ملتهب أو متهيّج. وحساسية الجلد للشمس معروفة في هذه الفصيلة وتُنتج حرقاً شمسياً أسرع وأشدّ من المعتاد بتعرّض قصير. وقد يهيّج المريء إن أُخذ ونام صاحبه قبل أن يستقرّ في المعدة، فيأتي ألم خلف عظم القصّ وحرقة عند البلع.',
    en: 'The commonest complaints are nausea, vomiting and diarrhoea, itching of the rectum or vagina from fungal overgrowth after the drug kills the normal flora, a swollen, black or hairy-looking tongue, and a sore or irritated throat. Skin sensitivity to sunlight is well known in this class and produces sunburn that is faster and more severe than usual after a short exposure. It can irritate the oesophagus if taken and followed by lying down before it settles in the stomach, giving pain behind the breastbone and burning on swallowing.'
  },
  warning: {
    ar: 'اطلب المساعدة العاجلة عند تورّم الوجه أو الحلق أو اللسان أو الشفتين أو العينين، أو صعوبة تنفّس أو بلع، أو طفح أو شرى، فهذه علامات تحسّس. واتصل بطبيبك فوراً عند صداع مع تشوّش رؤية أو ازدواج أو فقدان بصر، فقد يرفع الضغط داخل الجمجمة. وراجعه كذلك عند اصفرار أو نزف أو تكدّم غير معتاد أو ألم صدر أو تيبّس مفاصل وتورّمها، أو حمّى وقشعريرة وعودة علامات العدوى. واطلب الطبيب عند إسهال مائي أو دموي مع مغص وحمّى، ولو جاء بعد انتهاء العلاج بشهرين أو أكثر.',
    en: 'Seek urgent help for swelling of the face, throat, tongue, lips or eyes, difficulty breathing or swallowing, or a rash or hives, which are signs of an allergic reaction. Contact your doctor at once for headache with blurred or double vision or loss of vision, since it can raise the pressure inside the skull. See them too for yellowing, unusual bleeding or bruising, chest pain, or stiff and swollen joints, or fever, chills and the return of signs of infection. Call the doctor for watery or bloody diarrhoea with cramps and fever, even if it comes two months or more after treatment has ended.'
  },
  interact: {
    ar: 'أهمّ تعارضاته أنه يرتبط بالمعادن فيتعطّل: مضادّات الحموضة، ومكمّلات الكالسيوم ومنتجات الحليب، والحديد، والزنك، والمغنيسيوم، وأدوية القرحة الحاوية بزموت، كلها تُبطل مفعوله إن أُخذت معه، ولذلك تُباعد عنه مباعدة كافية كما تنصّ النشرة. وهو يُنقص فعالية موانع الحمل الهرمونية فتلزم وسيلة أخرى إلى جانبها. ويزيد أثر مميّعات الدم فيزيد خطر النزف، ولا يُجمع مع الأيزوتريتينوين لأن كليهما يرفع الضغط داخل الجمجمة. وبعض النشرات تُنبّه على الجمع مع البنسلينات لأنه يُضعف عملها.',
    en: 'Its most important interaction is that it binds to metals and is inactivated: antacids, calcium supplements and dairy products, iron, zinc, magnesium, and bismuth-containing ulcer medicines all cancel its effect if taken with it, so an adequate gap is left as the leaflet directs. It reduces the effectiveness of hormonal contraceptives, so another method is needed alongside. It increases the effect of blood thinners and so the risk of bleeding, and it is not combined with isotretinoin because both raise the pressure inside the skull. Some leaflets warn against combining it with penicillins, whose action it weakens.'
  },
  avoid: {
    ar: 'ممنوع على الحامل لأنه يؤذي الجنين، ويُتّصل بالطبيب فوراً إن حدث حمل أثناء العلاج، وتُخبَر الطبيبَ المرضعُ قبل البدء. وممنوع على الأطفال دون سنّ الثامنة إلا لضرورة طبية، لأنه يصبغ الأسنان صبغاً دائماً ويؤثّر في نموّ العظم. ولا يأخذه من تحسّس من التتراسيكلينات. ويُخبَر الطبيب بمرض الكلى وبالذئبة الحمامية قبل البدء. ويُتجنّب التعرّض الطويل أو غير الضروري للشمس ويُلبس الساتر ويُستعمل الواقي، ويُبلَّغ الطبيب عن أي حرق شمسي. ولا يُؤخذ الدواء بعد انتهاء صلاحيته لأن تحلّله يؤذي الكلى.',
    en: 'It is forbidden in pregnancy because it harms the fetus; the doctor is contacted at once if pregnancy occurs during treatment, and a breastfeeding mother tells her doctor before starting. It is forbidden in children under eight except out of medical necessity, because it stains the teeth permanently and affects bone growth. Anyone allergic to tetracyclines must not take it. The doctor is told about kidney disease and about lupus before starting. Prolonged or unnecessary sun exposure is avoided, covering clothing and sunscreen are used, and any sunburn is reported. Expired stock is never taken, because its breakdown products harm the kidneys.'
  },
  updated: '2026-09-10',
  src: [
    'https://medlineplus.gov/druginfo/meds/a682098.html'
  ]
};
